};

def theme_variants(theme_key: str) -> list[str] {
    key = (theme_key or "").strip().lower();
    candidates = THEME_VARIANTS.get(key, DEFAULT_VARIANTS);
    result: list[str] = [];
    for asset_id in candidates {
        if asset_id in TRANSFORM_PAIRS and asset_id not in result {
            result.append(asset_id);
        }
    }
    if not result {
        return list(DEFAULT_VARIANTS);
    }
    return result;
}
"}

