{"file_path": "/workspace/app.jac", "content": "import re;

def wr_parse_timing(text: str) -> dict {
    m = re.search(r"within\s+(\d+)\s+(minutes?|hours?)\s+(before|after)\s+food", text, re.IGNORECASE);
    if m is None {
        return {};
    }
    amount = int(m.group(1));
    if m.group(2).lower().startswith("hour") {
        amount = amount * 60;
    }
    relation = m.group(3).lower() + "_food";
    return {"window_minutes": amount, "relation": relation, "raw": m.group(0)};
}
"}

