def wr_rank_conflict_candidates(pairs: list[dict], budget: int) -> dict {
    anchored: list[dict] = [];
    reinforced: list[dict] = [];
    others: list[dict] = [];
    for p in pairs {
        if p.get("last_examined", False) {
            continue;
        }
        if p.get("shared_anchor", False) {
            anchored.append(p);
        } elif p.get("reinforced_this_turn", False) {
            reinforced.append(p);
        } else {
            others.append(p);
        }
    }
    ranked: list[dict] = anchored + reinforced + others;
    limit: int = budget if budget > 0 else 0;
    examine: list[dict] = ranked[:limit];
    queue: list[dict] = ranked[limit:];
    return {
        "examine": examine,
        "queue": queue,
        "examined_count": len(examine),
        "queued_count": len(queue)
    };
}
"}

