"""Return the exact symptom key from VOCAB_ANCHORS matching metric, or empty string on a miss."""
def wr_resolve_symptom(metric: str) -> str {
    for anchor in VOCAB_ANCHORS {
        if anchor["kind"] == "symptom" and anchor["key"] == metric {
            return anchor["key"];
        }
    }
    return "";
}
"}
